  boxes:[
   {scene:0,name:'战斗力与政体的九次摆动',en:'Nine Shifts of Force and Power',
    text:'<b>1. 贵族车骑 → 2. 步兵主力</b>：青铜战车让位给铁器步兵；希罗公民自备武装分得民权，战国国家发枪走向集权。<br><b>3. 草原骑射 → 4. 帝国大骑兵反扑</b>：撞上匈奴、帕提亚军民一体的骑射；汉武帝靠高榨取率办官马苑、卫青霍去病十万骑兵远征，逼出盐铁官营的财政国家（罗马晚三四百年才学波斯补课）。<br><b>5. 草原二次升级 → 6. 重骑拿地养兵</b>：马镫＋铁甲让重骑成王牌，叠加内附蛮族反客为主（五胡乱华 vs 民族大迁徙）；重骑太贵，没钱的国家只能“拿地换兵”（西欧采邑与骑士封建、北朝府兵与关陇集团），中间力量复活。<br><b>7. 募兵认将 → 8. 蒙古千户制 → 9. 火器与大众政治</b>：花钱雇兵导致“兵强马壮者为之”；成吉思汗以千户制统合轻骑诱敌、重骑冲锋与攻城重炮达冷兵器顶点；直到火枪让农夫几周就能打穿板甲，全民征兵把话语权重新推回普通人手里。'}
  ],
  html:`<p data-scene-text="0"><strong>社会阶梯并不是贵族发善心设计出来的，而是“战斗力决定话语权”的直接结果：战场上决定胜负的主力是谁、这套装备和训练谁出钱，政治权力就往哪边流。</strong>早期之所以全是贵族车兵和早期骑兵，一是青铜贵、战车训练门槛高，二是早期国家没有户籍和基层官僚，榨取率极低，组不起大步兵。等到冶铁术普及降了武器成本、农业人口激增，列国与城邦之间的灭国战逼出了严密的步兵方阵。<strong>但同样是步兵替代车骑，政治后果却在中西分了岔：</strong>希腊罗马是“薄国家”，打仗靠公民自掏腰包买盔甲刀枪（雅典连穷人去划桨也成了海军命根子），国家离不开他们，就得让渡出公民大会和保民官；中国战国走的是高榨取的变法路，按户籍抽丁、由官府作坊统一造兵器配发（“物勒工名”），农夫只出人头，筹码全在国君手里，所以换来的是拆掉世卿贵族的君主集权与军功爵。（主线印证：<a class="go" data-go="history-athens">雅典改革</a>、<a class="go" data-go="history-rome-plebs">罗马平民撤离</a>、<a class="go" data-go="history-china-warring-states">战国变法</a>）</p>
<p data-scene-text="1"><strong>定居国家之前不搞大骑兵，是因为没有马镫难发力，而且在农耕腹地对手全是同行步兵，没有改制的动力；直到扩张推到草原和荒原边界，撞上了匈奴（前 200 年白登之围）和帕提亚（前 53 年卡莱之战）。</strong>游牧民族是军民一体，放牧就是行军，打猎就是演习，零额外养兵成本，打得过就围、打不过就放风筝把步兵耗死。定居民族单兵骑射练不过牧民，翻盘靠的是大一统帝国的人口基数和财政榨取率：汉武帝在西北设三十六苑养官马四五十万匹，由<strong>卫青、霍去病</strong>率十万大骑兵集群深入大漠上千里包抄决战。同时代的罗马之所以没有卫青霍去病，一是帕提亚隔着沙漠没威胁到罗马核心区，二是早期罗马是地方自治的薄国家，抽不出全国养马的财力，要等三四百年后被萨珊波斯和草原骑兵夹击才补上这一课。<strong>代价是骑兵太烧钱（漠北一战十四万匹马去、回来不满三万），逼着汉武帝搞盐铁官营、算缗告缗，罗马戴克里先废除自治加派官吏督税，把专制财政国家推高了一个量级。</strong>（主线印证：<a class="go" data-go="history-rome-triumvirate">卡莱之战</a>、<a class="go" data-go="history-china-western-han">汉武帝北伐</a>、<a class="go" data-go="history-empire-dominate">戴克里先集权加税</a>）</p>
<p data-scene-text="2"><strong>好景不长，草原民族在帝国的军事压力下学会了铁甲锻造与严密编队，又在 4 世纪率先普及了高桥马鞍与双侧马镫，把人马动能锁在一起正面撞穿步兵线；偏偏这时汉魏和晚期罗马都因高榨取导致小农破产，贪便宜招蛮族骑兵“内附”，结果酿成东边的五胡乱华（304 年起）和西边的民族大迁徙（376 年哥特人过河、476 年西罗马灭亡）。</strong>这一步演变的政治后果最深远：人马俱甲的重装骑兵成了战场王牌，但一身铁甲、一匹战马加脱产训练的成本是步兵的十倍以上。西罗马灭亡后西欧货币枯竭，国王发不出饷，法兰克宫相查理·马特只好<strong>“拿地换兵”</strong>，把土地连同农奴分封给骑士当采邑——既然核心战斗力分散在自备马甲的骑士和领主手里，王权就必然虚化，长出了欧洲中世纪的封建制；同一时期缺钱少粮的西魏宇文泰搞<strong>府兵制</strong>，同样在政治上长出了垄断北周、隋、唐初百余年朝政的<strong>关陇贵族集团</strong>。（主线印证：<a class="go" data-go="history-empire-valentinian/2">阿德里安堡与哥特战法</a>、<a class="go" data-go="history-china-three-kingdoms">永嘉之乱</a>、<a class="go" data-go="history-empire-west-fall">西罗马的终结</a>）</p>
<p data-scene-text="3">往后冷兵器时代还有两道坎：一是帝国富裕后改花钱雇职业兵，结果<strong>兵认将不认国</strong>——罗马从马略私兵走到三世纪五十年换二十多个“军营皇帝”，中国从唐末藩镇走到五代武夫坐庄（<strong>“天子宁有种耶？兵强马壮者为之尔”</strong>）；二是 13 世纪成吉思汗把冷兵器推到顶峰——<strong>他靠的并不是单一轻骑兵，而是用千户制打散部落血缘，战略行军靠一人多马的轻骑长途奔袭，战场决战先用六成轻骑放箭、佯败诱敌拉散阵型，再用四成披甲重骑正面冲锋一锤定音，外加收编工匠的回回炮与火器攻城。</strong>直到火绳枪、燧发枪与滑膛炮成熟，才从根子上改写了算术：一个农夫练几周排队齐射就能打穿骑士攒了一辈子的板甲，大炮几天就能轰塌封建城堡。当战争在 1793 年法国大革命全民征兵后重新变成成百上千万普通人端着步枪上战场，政府要老百姓纳税挨枪子，就不得不拿普选权和公民权来换——两千多年前希腊罗马的“步兵革命”，在火器时代以现代大众政治的形式重新上演。（主线印证：<a class="go" data-go="history-rome-marius">马略军改</a>、<a class="go" data-go="history-empire-crisis">军营元首时期</a>）</p>`,
