   {label:'《史记·白起王翦列传》（长平之战：“秦王闻赵食道绝，王自之河内，赐民爵各一级，发年十五以上悉诣长平”）',url:'https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7073'}
